+/// The code npm gives a registry 404 for a package or a version.
+const NPM_NOT_FOUND_CODE: &str = "E404";
+
+/// Classifies one `npm view NAME@VERSION --json` run.
+///
+/// - exit 0 with output: `Exact`. `npm view` reports no checksum or yank flag, so the evidence says `None`.
+/// - exit 0 with no output: transient `MalformedResponse`. npm 11 answers a missing version with exit 1 and an `E404`
+///   error, so an empty success is not an answer about the registry.
+/// - failure with the structured `{"error":{"code":"E404"}}` body on stdout: `Absent`. Only that code is the
+///   registry's own "not found"; the free text around it is never read.
+/// - any other failure (another code, a body that is not that JSON, no body): transient `CommandFailed`, retried by
+///   the bounded policy. An unreachable registry, a rejected credential or a rate limit must never read as an absence.
+///
+/// A private package read without credentials is answered `E404` by the registry itself, so that case cannot be told
+/// from a missing one here.
+fn classify_npm_view(output: &CommandOutput, version: &Version) -> Attempt<ProviderObservationV1> {
+    if output.success() {
+        return if output.stdout_trimmed().is_empty() {
+            transient(ProviderIndeterminateCause::MalformedResponse, None)
+        } else {
+            settled(ProviderObservationV1::Exact {
+                evidence: ProviderEvidenceV1::RegistryVersion {
+                    version: version.clone(),
+                    checksum: None,
+                    yanked: None,
+                },
+            })
+        };
+    }
+    if npm_error_code(&output.stdout).as_deref() == Some(NPM_NOT_FOUND_CODE) {
+        return settled(ProviderObservationV1::Absent);
+    }
+    transient(ProviderIndeterminateCause::CommandFailed, None)
 }

